/**
 * Cytoscape ↔ canonical AFD shape adapter.
 *
 * Pure functions — no validation, no IO, no side effects.
 * Canonical shape (persistence format):
 *   { states: [{id, label}], transitions: [{from, symbol, to}],
 *     alphabet: string[], start: string|null, finals: string[] }
 *
 * DEVIATION from orchestrator contract: cyToAfd returns persistence format
 * (not simulator map format) because (a) it must be a drop-in for the
 * inline extractCanonical in afd_editor.js, and (b) snapshot_controller
 * compares .states/.transitions/.alphabet keys. Simulator wiring (S11/S12)
 * will convert via a separate afdToSimulatorInput helper.
 *
 * @module     local_graphitoubb/afd_adapter
 * @copyright  2026 GraphitoUBB
 * @license    https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define([],function(){return{cyToAfd:function(a){var t=[],i=[],n=null;a.nodes().forEach(function(a){t.push({id:a.id(),label:a.data("label")||a.id()}),a.data("start")&&(n=a.id()),a.data("final")&&i.push(a.id())});var r={},o=[],s=[];return a.edges().forEach(function(a){var t=a.data("symbol")||"";s.push({from:a.source().id(),symbol:t,to:a.target().id()}),t&&!r[t]&&(r[t]=!0,o.push(t))}),o.sort(),{states:t,transitions:s,alphabet:o,start:n,finals:i}},afdToCy:function(a){var t={},i=(a.states||[]).map(function(i){return t[i.id]=!0,{data:{id:i.id,label:i.label||i.id,start:i.id===(a.start||null),final:-1!==(a.finals||[]).indexOf(i.id)}}}),n=[];return(a.transitions||[]).forEach(function(a){t[a.from]&&t[a.to]&&n.push({data:{id:a.from+"__"+a.symbol+"__"+a.to,source:a.from,target:a.to,symbol:a.symbol}})}),{nodes:i,edges:n}},cyToAfdSimulator:function(a){var t=null,i=[],n={};a.nodes().forEach(function(a){n[a.id()]=!0,a.data("start")&&(t=a.id()),a.data("final")&&i.push(a.id())});var r={};a.edges().forEach(function(a){var t=a.data("symbol")||"",i=a.source().id(),o=a.target().id();t&&n[i]&&n[o]&&(r[i+":"+t]=o)});var o=(a.scratch("alphabet")||[]).slice();return{initialState:t,acceptStates:i,alphabet:o,transitions:r}}}});